window.VO = [{"id":"s01","text":"Google just lost four hundred and seventy-five billion dollars. In one day.","at":0.9,"t0":0.45,"t1":5.01},{"id":"s02","text":"Only Nvidia has ever lost more.","at":10.82,"t0":5.41,"t1":7.485},{"id":"s03","text":"Strange, because Google's sales had just grown twenty-five percent.","at":15.87,"t0":7.935,"t1":11.675},{"id":"s04","text":"Its cloud business more than doubled.","at":23.95,"t0":11.975,"t1":13.93},{"id":"s05","text":"So why the crash?","at":28.76,"t0":14.38,"t1":15.56},{"id":"s06","text":"The answer is in your search bar. Half of Google's money comes from search ads.","at":32.52,"t0":16.26,"t1":20.74},{"id":"s07","text":"But more searches now happen in AI Mode, where Google's AI just answers you.","at":42.38,"t0":21.19,"t1":25.7},{"id":"s08","text":"And Google admitted AI Mode earns less.","at":52.2,"t0":26.1,"t1":28.535},{"id":"s09","text":"Then there's the bill: fifty-one billion dollars in three months, on AI data centres.","at":58.27,"t0":29.135,"t1":34.315},{"id":"s10","text":"Over half a billion dollars a day.","at":69.33,"t0":34.665,"t1":36.535},{"id":"s11","text":"Two quarters in a row, Google spent more cash than it brought in.","at":74.07,"t0":37.035,"t1":40.48},{"id":"s12","text":"It's paying for the very AI that's eating into its search ads.","at":81.96,"t0":40.98,"t1":44.45},{"id":"s13","text":"Google isn't going broke.","at":90.1,"t0":45.05,"t1":46.525},{"id":"s14","text":"But Wall Street now has one question: is Google's AI eating Google?","at":93.85,"t0":46.925,"t1":50.945}];
